# Review package: ec3ba0b..HEAD

## Commits
832441a Fix review findings: type coercion, null handling, docs, and comments

## Files changed
 greet.js      | 21 +++++++++++++--------
 greet.test.js | 10 ++++++++++
 2 files changed, 23 insertions(+), 8 deletions(-)

## Diff
diff --git a/greet.js b/greet.js
index d54aaf3..6f2737a 100644
--- a/greet.js
+++ b/greet.js
@@ -1,29 +1,34 @@
+/**
+ * Greets a person with optional formatting.
+ *
+ * @param {*} name - The name to greet (defaults to 'Guest' for falsy values)
+ * @param {Object} options - Formatting options
+ * @param {string} options.prefix - Prefix to add before the name
+ * @param {string} options.suffix - Suffix to add after the name
+ * @param {boolean} options.uppercase - Whether to uppercase the name (applies to name only, not prefix/suffix)
+ * @returns {string} The formatted greeting
+ */
 function greet(name, options = {}) {
-  // Handle empty, null, or undefined input
-  const displayName = name || 'Guest';
+  const displayName = name ? String(name) : 'Guest';

-  // Extract options
-  const { prefix, suffix, uppercase } = options;
+  const { prefix, suffix, uppercase } = options || {};

-  // Build the formatted name
   let formattedName = displayName;

-  // Apply uppercase transformation if requested
+  // uppercase applies to the name only, preserving the original case of prefix/suffix
   if (uppercase) {
     formattedName = formattedName.toUpperCase();
   }

-  // Add prefix if provided
   if (prefix) {
     formattedName = `${prefix} ${formattedName}`;
   }

-  // Add suffix if provided
   if (suffix) {
     formattedName = `${formattedName} ${suffix}`;
   }

   return `Hello, ${formattedName}!`;
 }

 module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
index c53bd87..525a63c 100644
--- a/greet.test.js
+++ b/greet.test.js
@@ -39,10 +39,20 @@ test('greet with uppercase option', () => {

 test('greet with prefix, suffix, and uppercase', () => {
   const result = greet('jones', { prefix: 'Dr.', suffix: 'PhD', uppercase: true });
   assert.strictEqual(result, 'Hello, Dr. JONES PhD!');
 });

 test('greet with empty options object', () => {
   const result = greet('Charlie', {});
   assert.strictEqual(result, 'Hello, Charlie!');
 });
+
+test('greet handles non-string input with uppercase option', () => {
+  const result = greet(123, { uppercase: true });
+  assert.strictEqual(result, 'Hello, 123!');
+});
+
+test('greet handles null options gracefully', () => {
+  const result = greet('Alice', null);
+  assert.strictEqual(result, 'Hello, Alice!');
+});
